head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > customModelUnformatter]<br/>바인딩된 DataList 에서 Column 으로 값이 반영되기 전에 형식을 변환하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "Column 의 inputType='text', 'textImage' 인 경우에 동작합니다.",
        "반드시 customModelFormatter 속성을 함께 설정해야 합니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 파라미터로 DataList 의 값이 전달됩니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 반환값이 바인딩된 DataList 에서 Column 으로 반영되는 값으로 적용됩니다.",
        "하위 버전 호환을 위해 유지되는 속성이며 향후 제거(Deprecated)될 예정입니다.",
    ]
}



scwin.gVar = {
    // customModelUnformatter 호출 인자 기록 (출력 후 초기화)
    "calls" : []
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_customModelUnformatter.setValue("scwin.unfmt_phone");
    con_customModelFormatter.setValue("scwin.fmt_phone");
    con_inputType.setValue("text");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// customModelUnformatter : DataList 의 숫자 11자리 연락처를 000-0000-0000 형식으로 변환
scwin.unfmt_phone = function (data) {
    let args = [];
    for (let i = 0; i < arguments.length; i++) {
        args.push(String(arguments[i]));
    }
    scwin.gVar.calls.push("(" + args.join(", ") + ")");
    let str = String(data);
    if (/^[0-9]{11}$/.test(str)) {
        return str.substring(0, 3) + "-" + str.substring(3, 7) + "-" + str.substring(7);
    }
    return data;
}



// customModelFormatter (짝 속성) : 편집 값에서 하이픈을 제거하여 DataList 에 저장
scwin.fmt_phone = function (value) {
    return String(value).split("-").join("");
}



// comp 생성
//  - name : 고객명 / phone : 검증 대상 Column (Body Column 인덱스 1)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.calls = [];

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 연락처 Column(Body Column 인덱스 1) 에 설정, scwin.unfmt_phone 은 숫자 11자리를 000-0000-0000 으로 변환, scwin.fmt_phone 은 하이픈 제거\n[절차] 조건 선택 -> Target 재생성 -> 0행 연락처 셀 더블클릭 -> 010-9999-8888 입력 후 Enter -> DataList 값 확인\n[확인] DataList setCellData 버튼으로 1행 값을 01024681357 로 변경 시 함수 호출 인자와 화면 표시값 확인"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cUnformatter = con_customModelUnformatter.getValue();
    let cFormatter = con_customModelFormatter.getValue();
    let cInputType = con_inputType.getValue();

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="phone" name="phone" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "김민준", "phone" : "01012345678" },
        { "name" : "이서연", "phone" : "01098765432" },
        { "name" : "박지호", "phone" : "01055501234" },
        { "name" : "최유나", "phone" : "01077778888" }
    ], false);

    // 검증 대상 Column 마크업
    let attr = '';
    if (cUnformatter !== '') {
        attr += ' customModelUnformatter="' + cUnformatter + '"';
    }
    if (cFormatter !== '') {
        attr += ' customModelFormatter="' + cFormatter + '"';
    }
    if (cInputType === "textImage") {
        attr += ' imageSrc="/cm/images/contents/btn_folder.png"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="고객명"></w2:column>';
    strTarget += '<w2:column width="250" style="" inputType="text" id="column2" value="연락처(' + cInputType + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="250" style="" inputType="' + cInputType + '" id="phone"' + attr + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 1, 3, 4 : 초기 로딩 시 함수 인자 / DataList 값 / 화면 표시값
    setTimeout(function () {
        scwin.printResult("");
    }, 100);
}



// 함수 호출 인자(호출된 경우만) + DataList 값 + 화면 표시값 출력 후 호출 기록 초기화
scwin.printResult = function (prefix) {
    let lines = [];
    if (scwin.gVar.calls.length > 0) {
        lines.push(prefix + "함수 호출 인자 : " + scwin.gVar.calls.join(" / "));
    }
    scwin.gVar.calls = [];
    let dataArr = [];
    let displayArr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        dataArr.push(i + "행='" + dlt_bind.getCellData(i, "phone") + "'");
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + i + "_1']");
        displayArr.push(i + "행='" + (td ? td.textContent.trim() : "") + "'");
    }
    lines.push("DataList phone : " + dataArr.join(" / "));
    lines.push("화면 표시값 : " + displayArr.join(" / "));
    wf_body_bottom.getObj("scwin").setReturnValue(lines.join("\n"));
}



// validation 3, 4 : DataList 값 변경(setCellData) 시 함수 호출 인자와 화면 표시값
scwin.btn_setCellData_onclick = function () {
    dlt_bind.setCellData(1, "phone", "01024681357");
    setTimeout(function () {
        scwin.printResult("setCellData(1, phone, 01024681357) -> ");
    }, 100);
}



// validation 2, 4 : 셀 편집 후 DataList 저장값과 화면 표시값 비교
scwin.btn_checkDataList_onclick = function () {
    scwin.printResult("");
}
